const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v==null||!Number.isFinite(v)?'—':Math.round(v).toLocaleString('en-IN');
const money=(v,currency=state.currency)=>v==null||!Number.isFinite(v)?'—':`${currency==='INR'?'₹':'AED '}${num(v)}`;
const pct=v=>v==null||!Number.isFinite(v)?'—':`${v.toFixed(2)}%`;
const calcDelta=(v,b)=>v!=null&&Number.isFinite(v)&&b!=null&&Number.isFinite(b)&&b!==0?((v-b)/b)*100:(v===0&&b===0?0:null);
const delta=(v,inverse=false)=>v==null?'<span class="delta">n/a</span>':`<span class="delta ${inverse?v>0?'negative':'':v<0?'negative':''}">${icon(v>=0?'upRight':'down',10)}${v<0?'−':v>0?'+':''}${Math.abs(v).toFixed(1)}%</span>`;
