function shiftISO(iso,delta){const dt=new Date(String(iso).slice(0,10)+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+delta);return dt.toISOString().slice(0,10)}
function shortDate(d){if(typeof d==='string'&&d.includes('-'))return new Date(d.slice(0,10)+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'});return `${d} Oct`}
