const clientById=id=>clients().find(c=>c.id===id)||clients()[0];
const accounts=()=>baseAccounts.map(a=>({...a,client:Object.hasOwn(db.mapping,a.id)?db.mapping[a.id]:a.client,currency:a.currency||baseClients.find(c=>c.id===a.client)?.currency||'INR'}));
const clientAccounts=id=>accounts().filter(a=>a.client===id);
const canEdit=()=>db.role!=='staff';const isAdmin=()=>db.role==='admin';
const days=()=>{if(!window.__LIVE)return state.period==='yesterday'?[22]:state.period==='7d'?[16,17,18,19,20,21,22]:Array.from({length:22},(_,i)=>i+1);const end=window.__LIVE.endDate,n=state.period==='yesterday'?1:state.period==='7d'?7:(window.__LIVE.mtdDays||Number(end.slice(-2)));return Array.from({length:n},(_,i)=>shiftISO(end,i-n+1))};
const metricRow=(a,day)=>{
 if(a.days){const row=a.days[day]||a.days[String(day)]||{};return{spend:Number(row.spend)||0,leads:Number(row.leads)||0,clicks:Number(row.clicks)||0,impressions:Number(row.impressions)||0}}
 if(a.id==='f-meta'&&day===22)return{spend:0,leads:0,clicks:0,impressions:0};
 const idx=baseAccounts.findIndex(x=>x.id===a.id);let factor=day===22?1:0.77+0.15*Math.sin(day*1.47+idx*.43)+day*.006;
 const leadFactor=day===22?1:factor*(.88+.12*Math.cos(day*.7+idx*.22));
 const fallback=a.id==='f-meta';
 return{spend:Math.round((fallback?2200:a.spend)*factor),leads:Math.round((fallback?6:a.leads)*leadFactor),clicks:Math.round((fallback?260:a.clicks)*factor),impressions:Math.round((fallback?18000:a.impressions)*factor)};
};
const aggregate=(rows,selectedDays)=>{let r={spend:0,leads:0,clicks:0,impressions:0};for(const a of rows)for(const day of selectedDays){const m=metricRow(a,day);for(const k of Object.keys(r))r[k]+=m[k]}return{...r,cpa:r.leads?r.spend/r.leads:null,ctr:r.impressions?r.clicks/r.impressions*100:null}};
const filterClients=()=>clients().filter(c=>c.currency===state.currency&&(state.clientFilter==='all'||c.id===state.clientFilter)&&c.name.toLowerCase().includes(state.search.toLowerCase())).filter(c=>state.platform==='all'||clientAccounts(c.id).some(a=>a.platform===state.platform));
const tableClients=()=>clients().filter(c=>(state.tableCurrency==='all'||c.currency===state.tableCurrency)&&(state.clientFilter==='all'||c.id===state.clientFilter)&&c.name.toLowerCase().includes(state.search.toLowerCase())&&(state.platform==='all'||clientAccounts(c.id).some(a=>a.platform===state.platform)));
const filteredAccounts=(id=null)=>{const ids=id?[id]:filterClients().map(c=>c.id);return accounts().filter(a=>ids.includes(a.client)&&(state.platform==='all'||a.platform===state.platform))};
const totals=id=>aggregate(filteredAccounts(id),days());
const comparison=(rows,which)=>{const selected=days(),n=selected.length;let ds=which==='prev'?selected.map(d=>typeof d==='string'?shiftISO(d,-n):d-n):window.__LIVE?Array.from({length:7},(_,i)=>shiftISO(selected[0],i-7)):[15,16,17,18,19,20,21];const r=aggregate(rows,ds);if(which==='avg'){for(const k of ['spend','leads','clicks','impressions'])r[k]=r[k]/7*n;r.cpa=r.leads?r.spend/r.leads:null;r.ctr=r.impressions?r.clicks/r.impressions*100:null}return r};
