function route(){closeModal(false);const bits=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);let page=bits[0]||'portfolio';if(page==='telegram')page='reports';state.clientId=null;state.accountId=null;state.campaignId=null;state.adsetId=null;state.adId=null;state.page=['portfolio','clients','accounts','flags','reviews','reports','feedback','settings','login'].includes(page)?page:'portfolio';if(page==='clients'&&bits[1]){state.clientId=clientById(bits[1]).id;state.tab=bits[2]||'overview';if(bits[2]==='campaigns'&&bits[3])state.campaignId=bits[3];if(bits[2]==='adsets'&&bits[3])state.adsetId=bits[3];if(bits[2]==='ads'&&bits[3])state.adId=bits[3];state.currency=clientById(state.clientId).currency}if(page==='accounts'&&bits[1])state.accountId=accounts().some(a=>a.id===bits[1])?bits[1]:null;if(page==='settings')state.settingsTab=bits[1]||'clients';state.search='';state.sidebar=false;state.editReview=false;render();window.scrollTo(0,0)}
function go(path){closeModal();if(location.hash===`#/${path}`){route();return}location.hash='/'+path}
function updateURL(){const p=new URLSearchParams();if(state.currency!=='INR')p.set('currency',state.currency);if(state.tableCurrency!=='all')p.set('tableCurrency',state.tableCurrency);if(state.platform!=='all')p.set('platform',state.platform);if(state.clientFilter!=='all')p.set('client',state.clientFilter);if(state.period!=='yesterday')p.set('period',state.period);history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+(location.hash||'#/portfolio'))}
function brand(){return'<div class="brand"><span class="brand-symbol"><i></i><i></i><i></i></span>creativheads<sup>®</sup></div>'}
function navItem(page,label,ico,count=''){const active=state.page===page||(page==='clients'&&state.clientId);return`<a href="#/${page}" class="nav-item ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${count?`<span class="count ${page==='flags'?'attention':''}">${count}</span>`:''}</a>`}
function sidebar(){return`<aside class="sidebar ${state.sidebar?'open':''}" aria-label="Main navigation">${brand()}<button class="workspace-select" data-action="workspace"><span class="workspace-icon">${icon('grid',16)}</span><span>Ad Reports<small>CreativHeads workspace</small></span>${icon('down',12)}</button><nav><div class="nav-group"><div class="nav-label">WORKSPACE</div>${navItem('portfolio','Portfolio','grid')}${navItem('clients','Clients','users')}${navItem('reviews','AI reviews','spark',readyReviews().length)}${navItem('flags','Flags & alerts','flag',flags().length)}</div><div class="nav-group"><div class="nav-label">REPORTING</div>${navItem('reports','Client reports','send')}<a href="/creatives" class="nav-item">${icon('grid')}<span>Ad creatives</span></a>${navItem('feedback','Lead feedback','message')}</div><div class="nav-group"><div class="nav-label">MANAGEMENT</div>${navItem('accounts','Ad accounts','account')}${navItem('settings','Settings','settings')}</div></nav><div class="sidebar-bottom"><div class="sync-box"><strong><span class="dot"></span>Reporting, on a rhythm.</strong>Daily reports at 09:00 IST<a href="#/reports" class="tiny-link">View reporting activity ${icon('arrow',12)}</a></div><div class="profile"><span class="avatar">SM</span><div><div class="name">Souban</div><small>${{admin:'Workspace admin',performance:'Performance team',staff:'Read-only staff'}[db.role]}</small></div><button aria-label="Switch preview role" title="Switch preview role" data-action="profile">${icon('down',14)}</button></div></div></aside><div class="mobile-shade" data-action="menu" aria-hidden="true"></div>`}
function topbar(){const titles={portfolio:'Portfolio',clients:state.clientId?clientById(state.clientId).name:'Clients',reviews:'AI reviews',flags:'Flags & alerts',reports:'Client reports',feedback:'Lead feedback',accounts:state.accountId?'Account detail':'Ad accounts',settings:'Settings'};return`<header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumbs"><span>Workspace</span>${icon('chevron',10)}<strong>${esc(titles[state.page]||'Portfolio')}</strong></div><div class="topbar-right"><button class="global-search" data-action="search" aria-label="Search workspace">${icon('search',15)}<span>Search workspace...</span><kbd>⌘ K</kbd></button><span class="top-divider"></span><span class="demo-label">STAFF WORKSPACE</span><button class="icon-btn help-trigger" data-action="help" aria-label="About this prototype">${icon('help',17)}</button><button class="icon-btn" data-action="notifications" aria-label="View notifications">${icon('bell',17)}</button></div></header>`}
function heading(title,desc,actions='',eyebrow='CREATIVHEADS · AD REPORTS'){return`<div class="eyebrow">${eyebrow}</div><div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function picker(key,label,options,ico='',group='filter'){const selected=state[key];return `<details class="filter-dropdown" data-picker><summary class="select-wrap" role="button" aria-haspopup="listbox" aria-expanded="false" aria-label="${esc(label)}">${ico?icon(ico,13):''}<span>${esc(options.find(([v])=>v===selected)?.[1]||options[0][1])}</span>${icon('down',12)}</summary><div class="filter-menu" role="listbox" aria-label="${esc(label)}">${options.map(([v,l])=>`<button type="button" role="option" aria-selected="${v===selected}" data-action="${group==='v3'?'v3-select-filter':'set-filter'}" data-key="${key}" data-value="${v}">${esc(l)}${v===selected?icon('check',12):''}</button>`).join('')}</div></details>`;}
function filters(showClient=true,showPlatform=true){return `<div class="filterbar"><div class="filter-left">${showClient?picker('clientFilter','Filter by client',[['all','All clients'],...clients().map(c=>[c.id,c.name])],'users'):''}${showPlatform?picker('platform','Filter by platform',[['all','All platforms'],['meta','Meta Ads'],['google','Google Ads']],'account'):''}${picker('period','Reporting period',[['yesterday',window.__LIVE?`Yesterday, ${shortDate(window.__LIVE.endDate)}`:'Yesterday, 22 Oct'],['7d','Last 7 days'],['mtd','This month']],'calendar')}</div><div class="filter-right"><div class="freshness"><span class="dot"></span>${window.__LIVE?esc(window.__LIVE.syncedLabel):'Sample sync · 08:20 IST'}</div>${!state.clientId?`<span class="date-label">Totals currency</span><div class="segmented" aria-label="Reporting currency"><button class="${state.currency==='INR'?'active':''}" data-action="currency" data-value="INR">INR ₹</button><button class="${state.currency==='AED'?'active':''}" data-action="currency" data-value="AED">AED</button></div>`:`<span class="badge neutral">${state.currency}</span>`}</div></div>`}

function sparkline(i){const paths=['M0 23 10 19 20 22 30 12 40 15 50 5 60 9 70 2','M0 23 10 20 20 12 30 16 40 9 50 12 60 4 70 1','M0 5 10 7 20 5 30 11 40 10 50 18 60 17 70 23','M0 23 10 21 20 14 30 17 40 12 50 4 60 9 70 3'];return`<svg class="sparkline" viewBox="0 0 70 27" aria-hidden="true"><path d="${paths[i]}" fill="none" stroke="#91ad7b" stroke-width="1.5"/></svg>`}
function metricCards(id=null){const a=filteredAccounts(id),t=totals(id),prev=comparison(a,'prev'),avg=comparison(a,'avg');const list=[['Total ad spend','spend','wallet',money(t.spend),false],['Leads generated','leads','users',num(t.leads),false],['Cost per lead','cpa','target',money(t.cpa),true],['Click-through rate','ctr','click',pct(t.ctr),false]];return`<div class="metrics">${list.map(([label,key,ico,val,inv],i)=>`<section class="metric" id="metric-${key}" aria-label="${label}: ${val}"><div class="metric-top"><span>${label}</span>${icon(ico)}</div><div class="metric-value">${val}</div>${t[key]?sparkline(i):''}<div class="metric-comparison">${delta(calcDelta(t[key],prev[key]),inv)}<span>vs ${state.period==='yesterday'?'previous day':'previous period'}</span></div><div class="metric-comparison secondary">${delta(calcDelta(t[key],avg[key]),inv)}<span>vs ${state.period==='yesterday'?'7-day avg':'prior 7-day daily avg × days'}</span></div></section>`).join('')}</div>`}
function chart(id=null){const arr=window.__LIVE?Array.from({length:state.chartRange},(_,i)=>shiftISO(window.__LIVE.endDate,i-state.chartRange+1)):Array.from({length:state.chartRange},(_,i)=>23-state.chartRange+i),rows=filteredAccounts(id);const series=arr.map(d=>aggregate(rows,[d])[state.metric]||0),previous=arr.map(d=>aggregate(rows,[typeof d==='string'?shiftISO(d,-state.chartRange):d-state.chartRange])[state.metric]||0),max=Math.max(...series,...previous,1)*1.23;const W=600,H=196,L=47,R=18,T=16,B=31,x=i=>L+(W-L-R)*i/(series.length-1),y=v=>H-B-(H-T-B)*v/max;const path=(s)=>s.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');const total=series.reduce((a,b)=>a+b,0),before=previous.reduce((a,b)=>a+b,0);return`<section class="card"><div class="card-header"><div><h2>Performance over time</h2><p>${state.metric==='spend'?'A little context behind the numbers.':'Lead volume across your selected accounts.'}</p></div><div class="segmented"><button data-action="chart-metric" data-value="spend" class="${state.metric==='spend'?'active':''}">Spend</button><button data-action="chart-metric" data-value="leads" class="${state.metric==='leads'?'active':''}">Leads</button></div></div><div style="display:flex;justify-content:space-between;padding:0 21px 7px"><div class="chart-legends"><span><i class="legend-line"></i>Current ${state.chartRange} days</span><span><i class="legend-line previous"></i>Previous ${state.chartRange} days</span></div><button class="text-link" data-action="chart-range" style="font-size:9px">Last ${state.chartRange} days ${icon('down',10)}</button></div><div class="chart-wrap"><div class="chart-tooltip"></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${state.metric==='spend'?'Ad spend':'Leads'} trend for the last ${state.chartRange} days"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#c1d6a6" stop-opacity=".55"/><stop offset="100%" stop-color="#eaf2e0" stop-opacity=".07"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=max*i/3,yy=y(v);return`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#edf0e9" stroke-dasharray="3 4"/><text x="${L-9}" y="${yy+3}" text-anchor="end" fill="#a2ab99" font-size="8" font-family="Hanken,Arial">${state.metric==='spend'?(state.currency==='INR'?'₹':'')+(v>=1000?(v/1000).toFixed(0)+'k':num(v)):num(v)}</text>`}).join('')}<path d="${path(series)} L${x(series.length-1)} ${H-B} L${L} ${H-B}Z" fill="url(#chart-fill)"/><path d="${path(previous)}" fill="none" stroke="#c4cdbc" stroke-width="1.5" stroke-dasharray="4 4"/><path d="${path(series)}" fill="none" stroke="#71925c" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/>${series.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="white" stroke="#71925c" stroke-width="1.8"/>${state.chartRange===7||i%2===0||i===series.length-1?`<text x="${x(i)}" y="${H-9}" text-anchor="middle" fill="#9ea993" font-size="8" font-family="Hanken,Arial">${shortDate(arr[i])}</text>`:''}<rect x="${x(i)-16}" y="${T}" width="32" height="${H-T-B}" fill="transparent" tabindex="0" role="img" aria-label="${shortDate(arr[i])}ober: ${state.metric==='spend'?money(v):num(v)+' leads'}" data-chart-point="${shortDate(arr[i])} · ${state.metric==='spend'?money(v):num(v)+' leads'}" data-point-x="${x(i)/W*100}" data-point-y="${y(v)/H*100}"/>`).join('')}</svg></div><div class="chart-bottom"><span>${icon('info',11)}Totals shown in ${state.currency}</span><span class="chart-stat">${icon('trend',12)}${Math.abs(calcDelta(total,before)||0).toFixed(1)}% ${total>=before?'higher':'lower'} than previous period</span></div></section>`}
function aiSpotlight(){const ready=readyReviews().sort((a,b)=>({high:0,medium:1,low:2}[a.severity]-{high:0,medium:1,low:2}[b.severity]));return`<section class="card ai-spotlight"><div class="ai-topline"><span>${icon('spark',15)}YOUR SECOND PAIR OF EYES</span><span class="mini-tag">AI REVIEW</span></div><div class="ai-headline"><span class="big-number">${String(ready.length).padStart(2,'0')}</span><p>reviews ready for<br>a human touch.</p></div><div class="ai-list">${ready.slice(0,3).map(c=>`<a href="#/clients/${c.id}/review" class="ai-row">${avatar(c)}<span>${esc(c.name)}<small>${window.__LIVE?`${money(aggregate(clientAccounts(c.id),days()).spend,c.currency)} · ${num(aggregate(clientAccounts(c.id),days()).leads)} leads`:c.id==='a'?'Cost per lead needs a look':c.id==='c'?'Budget is ahead of plan':c.id==='e'?'Delivery below target':'Lead efficiency improved'}</small></span>${severity(c)}</a>`).join('')||'<p class="subtext" style="color:#bacbb0;padding:15px 0">You’re all caught up. Nicely done.</p>'}</div><div class="ai-footer"><button data-action="go" data-value="reviews">Open review queue ${icon('arrow',14)}</button><span>${ready.length>3?'+'+(ready.length-3)+' more':'Staff review required'}</span></div></section>`}
function miniBars(c){return`<div class="mini-bars" aria-hidden="true">${[.3,.5,.4,.75,.6,.85,1].map((x,i)=>`<span style="height:${Math.max(2,(c.id==='f'&&i===6?0:x)*18)}px"></span>`).join('')}</div>`}
function clientTable(full=false){let rows=tableClients();rows.sort((a,b)=>{if(state.sort==='name')return a.name.localeCompare(b.name)*state.sortDirection;const av=aggregate(filteredAccounts(a.id),days())[state.sort],bv=aggregate(filteredAccounts(b.id),days())[state.sort];return((av||0)-(bv||0))*state.sortDirection});return`<section class="card table-card"><div class="card-header"><div class="table-title"><h2>${full?'Your clients':'Client performance'}</h2><span class="subcount">${rows.length}</span></div><div class="table-tools">${picker('tableCurrency','Filter clients by currency',[['all','All currencies'],['INR','INR clients'],['AED','AED clients']])}<label class="search-field">${icon('search',12)}<input data-search="clients" aria-label="Search clients" placeholder="Search clients..." value="${esc(state.search)}"/></label><button class="btn small" data-action="table-filters">${icon('filter',13)}Filters</button></div></div><div class="table-scroll"><table><thead><tr><th><button class="sort" data-action="sort" data-value="name">Client ${icon('sort',10)}</button></th><th>Platforms</th><th><button class="sort" data-action="sort" data-value="spend">Ad spend ${icon('sort',10)}</button></th><th><button class="sort" data-action="sort" data-value="leads">Leads ${icon('sort',10)}</button></th><th><button class="sort" data-action="sort" data-value="cpa">Cost / lead ${icon('sort',10)}</button></th><th>Cost / booking · 7d</th><th>Feedback</th><th>Client handoff</th><th>Budget pacing</th><th>AI review</th><th aria-label="Open client"></th></tr></thead><tbody>${rows.map(c=>{const t=totals(c.id),prev=comparison(filteredAccounts(c.id),'prev');return`<tr class="clickable" data-action="go" data-value="clients/${c.id}" tabindex="0" aria-label="Open ${esc(c.name)}"><td><div class="client-name-cell">${avatar(c)}<div><a class="client-row-link" href="#/clients/${c.id}"><strong>${esc(c.name)}</strong></a><small>${esc(c.sector)} · ${c.currency}</small></div></div></td><td>${platformIcons(c.id)}</td><td class="numeric">${money(t.spend,c.currency)}${t.spend===0?'<small class="cell-sub">No spend</small>':''}<div class="table-mini">${delta(calcDelta(t.spend,prev.spend))}</div></td><td class="numeric">${num(t.leads)}</td><td class="numeric">${money(t.cpa,c.currency)}</td>${v3.portfolioCells(c)}<td class="pacing-cell">${c.pace==null?'<span class="cell-sub">No budget set</span>':`<div class="pacing-label"><span>${c.pace}%</span><span>${c.pace>115?'Ahead':c.pace<80?'Behind':'On track'}</span></div><div class="progress-track"><div class="progress-fill ${c.pace>115||c.pace<80?'warn':''}" style="width:${Math.min(c.pace/1.3,100)}%"></div></div>`}</td><td>${c.status==='approved'?statusBadge('approved'):severity(c)}</td><td><a class="icon-btn" href="#/clients/${c.id}" aria-label="View ${esc(c.name)}">${icon('chevron',13)}</a></td></tr>`}).join('')||'<tr><td colspan="11"><div class="empty-state">No clients match these filters. Clear the client, currency or platform filter.</div></td></tr>'}</tbody></table></div><div class="table-footer"><span>${rows.length?`Showing ${rows.length} of ${clients().length} clients`:'No clients found'} · ${state.tableCurrency==='all'?'All currencies · row values in client currency':state.tableCurrency+' clients'}</span><div class="pagination"><button disabled aria-label="Previous page">${icon('chevron',11).replace('class="icon"','class="icon" style="transform:rotate(180deg)"')}</button><button class="active" aria-current="page">1</button><button disabled aria-label="Next page">${icon('chevron',11)}</button></div></div></section>`}
function bottomNote(){return`<footer class="bottom-note"><span>${icon('shield',11)}${window.__LIVE?(window.__LIVE.accounts.some(x=>x.ads?.length)?'Live Meta data for the selected dates, by campaign, ad set and ad. Google Ads is not connected.':'Meta account totals for the selected dates. Campaign and ad rows are still syncing, and Google Ads is not connected.'):'Sample workspace · All figures are illustrative sample data.'}</span><span>Made for better decisions. CreativHeads®</span></footer>`}
function portfolio(full=false){return heading(full?'Every client. One workspace.':'Portfolio overview',full?'Keep every account, outcome, and next step in view.':'The big picture, with the details that matter.',`<button class="btn" data-action="export">${icon('download',14)}Export<span class="hide-mobile"> report</span></button>`) +filters()+(!full?metricCards()+v3.workflowStrip()+`<div class="dashboard-grid">${chart()}${aiSpotlight()}</div>`:'')+clientTable(full)+bottomNote()}
function clientTabs(id){return`<div class="tabs"><button data-action="client-tab" data-value="overview" class="${state.tab==='overview'?'active':''}">Overview</button><button data-action="client-tab" data-value="review" class="${state.tab==='review'?'active':''}">AI review <span class="badge neutral">${clientById(id).status==='skipped'?0:1}</span></button><button data-action="client-tab" data-value="accounts" class="${state.tab==='accounts'?'active':''}">Ad accounts</button><button data-action="client-tab" data-value="flags" class="${state.tab==='flags'?'active':''}">Flag history</button><button data-action="client-tab" data-value="configuration" class="${state.tab==='configuration'?'active':''}">Configuration</button></div>`}
function budgetCard(c){if(c.budget==null||c.pace==null)return`<section class="card section-pad"><div class="section-head"><h2>Monthly budget</h2><span class="badge neutral">Not set</span></div><p class="subtext" style="line-height:1.7">No monthly budget is stored for this account, so pacing is not shown.</p></section>`;const mtd=c.budget*22/31*c.pace/100;return`<section class="card section-pad"><div class="section-head"><h2>Monthly budget</h2><span class="badge ${c.pace>115||c.pace<80?'warning':'success'}">${c.pace>115?'Ahead of plan':c.pace<80?'Under pacing':'On track'}</span></div><div class="budget-ring-wrap"><div class="budget-ring" style="--progress:${Math.min(mtd/c.budget*100,100)}"><div>${Math.round(mtd/c.budget*100)}%<small>of budget used</small></div></div><div class="budget-legend"><strong>${money(mtd,c.currency)}</strong>of ${money(c.budget,c.currency)}</div></div><div class="definition-list"><div><span>Month-to-date pacing</span><strong>${c.pace}%</strong></div><div><span>Remaining budget</span><strong>${money(Math.max(0,c.budget-mtd),c.currency)}</strong></div><div><span>Illustrative month projection</span><strong>${money(c.budget*c.pace/100,c.currency)}</strong></div></div><div class="note-box" style="margin-top:20px">${icon('info',14)}Budget pacing is an illustrative snapshot, independent of the selected reporting period.</div></section>`}
function platformSplit(c){return`<section class="card section-pad"><div class="section-head"><h2>Platform breakdown</h2><span class="date-label">${periodLabel()}</span></div><div class="platform-split">${['meta','google'].filter(p=>state.platform==='all'||p===state.platform).map(p=>{const rows=clientAccounts(c.id).filter(a=>a.platform===p),m=aggregate(rows,days());return`<div class="split-block"><div class="split-name">${platformIcon(p)}${p==='meta'?'Meta Ads':'Google Ads'}</div><div class="split-value">${rows.length?money(m.spend,c.currency):'—'}</div><div class="split-info">${rows.length?`${num(m.leads)} leads · ${money(m.cpa,c.currency)} / lead`:'No account connected'}</div></div>`}).join('')}</div></section>`}
function clientPage(){return v3.clientPage()}
function liveReviewSummary(c){if(!window.__LIVE)return 'Review the latest account totals and confirm lead quality before changing budget.';const y=aggregate(clientAccounts(c.id),[window.__LIVE.endDate]);if(!y.spend)return 'No spend on '+dateFormat(window.__LIVE.endDate)+'.';return c.name+' spent '+money(y.spend,c.currency)+' and recorded '+num(y.leads)+' leads on '+dateFormat(window.__LIVE.endDate)+', at '+money(y.cpa,c.currency)+' per lead. Confirm lead quality before changing budget.'}
function reviewSummary(c){return c.editedSummary||({a:'Lead volume held steady, but Google cost per lead needs attention. Review search quality before making the next budget decision.',b:'Lead generation is efficient and budget pacing is stable. Continue monitoring lead quality as volume grows.',c:'Delivery is strong, but the monthly budget is running ahead of plan. Rebalance the remaining daily allocation.',d:'Meta is generating a healthy flow of leads while spending stays close to plan. Validate lead quality before scaling.',e:'Delivery is below the planned budget. Check campaign limits and eligibility before increasing allocations.',f:'No review: zero spend on 22 October. The review was skipped to avoid unnecessary usage.',g:'Lead delivery and spending remain steady. Review incoming enquiry quality and maintain the current monitoring cadence.'}[c.id])||liveReviewSummary(c)}
function baseRecommendations(c){if(c.id==='a')return[{title:'Review Google search terms',priority:'p1',platform:'google',metric:'cpa',basis:'Google CPA · ₹520',action:'Check the search terms report and add negatives for irrelevant queries. Compare incoming lead quality with the previous week before changing bids.',impact:'Reduce wasted spend and improve enquiry relevance.'},{title:'Compare lead quality across platforms',priority:'p2',platform:'both',metric:'leads',basis:'Meta 30 leads · Google 8 leads',action:'Review a sample of leads from both platforms with the client team. Use qualified lead rates alongside cost per lead for the next budget decision.',impact:'Prioritise qualified enquiries, not just lead volume.'}];if(c.id==='c')return[{title:'Review the remaining monthly allocation',priority:'p1',platform:'both',metric:'spend',basis:'Budget pacing · 121%',action:'Check scheduled campaign activity and the remaining monthly budget. Agree an updated daily allocation with the account owner.',impact:'Bring projected spend closer to the approved budget.'}];if(c.id==='e')return[{title:'Check campaign delivery constraints',priority:'p1',platform:'both',metric:'spend',basis:'Budget pacing · 74%',action:'Review eligibility, audience size, scheduling and bid limits in each ad platform. Document any constraints before recommending a budget change.',impact:'Identify why campaigns are delivering below plan.'}];return[{title:'Validate lead quality before scaling',priority:'p2',platform:c.id==='d'?'meta':'both',metric:'leads',basis:`Yesterday · ${num(aggregate(clientAccounts(c.id),[window.__LIVE?window.__LIVE.endDate:22]).leads)} leads`,action:'Compare lead quality and response times with the previous week. Document any consistent patterns before recommending additional budget.',impact:'Keep growth aligned with meaningful business outcomes.'}]}
function recommendations(c){return [...baseRecommendations(c),...v3.qualityRecommendations(c)]}
function reviewPanel(c){if(c.status==='skipped'||!c.ai)return`<section class="card"><div class="empty-state">${icon('spark',30)}<h3>${!c.ai?'AI review is disabled':'No review: zero spend'}</h3><p>${!c.ai?'Enable reviews in this client’s configuration.':'The latest report date has no spend. No review usage is recorded.'}</p><button class="btn" style="margin-top:18px" data-action="client-tab" data-value="overview">Back to overview</button></div></section>`;const recs=recommendations(c);const revision=c.revision||1;return`<section class="card">${!canEdit()?'<div class="readonly-note">Read-only role · Switch preview role to try feedback and approvals.</div>':''}<div class="review-summary"><div class="section-head"><div class="review-heading">${icon('spark',18)}<h2>Daily performance review</h2></div>${statusBadge(c.status)}</div><div style="display:flex;gap:8px;align-items:center;margin-bottom:12px"><span class="date-label">${window.__LIVE?dateFormat(window.__LIVE.endDate):'22 October 2026'}</span>${severity(c)}<span class="date-label">${c.confidence==null?'Rules-based':c.confidence+'% confidence'}</span></div>${state.editReview?`<label class="field"><span class="date-label">Editable summary · the original is preserved</span><textarea class="inline-edit" id="review-edit">${esc(reviewSummary(c))}</textarea></label>`:`<p>${esc(reviewSummary(c))}</p>`}</div><div class="review-sections">${v3.qualityReviewSnippet(c)}<h4>What went well</h4><div class="insight">${icon('checkCircle',16)}<span>${c.id==='a'?'Meta generated 30 leads at ₹276 per lead. It contributed most of the client’s lead volume.':c.id==='c'?'Both connected platforms generated leads on the report date.':'Lead activity gives the team a useful baseline for the next review.'}</span></div><h4>Areas to watch</h4><div class="insight concern">${icon('warning',16)}<span>${c.id==='a'?'Google CPA of ₹520 needs a closer look at search quality. This sample review uses an illustrative 7-day baseline of ₹397.':c.id==='c'?'Budget pacing is at 121% of the expected spend.':c.id==='e'?'Budget pacing is at 74% of the expected spend.':'Lead counts do not indicate qualification or revenue. Validate outcomes with the client team.'}</span></div><h4>Recommended next steps · ${recs.length}</h4>${recs.map((r,i)=>{const f=db.feedback[`${c.id}:${revision}:${i}`]||{};return`<article class="recommendation"><div class="rec-top"><span class="badge ${r.priority==='p1'?'warning':'neutral'}">${r.priority.toUpperCase()}</span><h3>${esc(r.title)}</h3><span class="badge neutral">${r.platform==='both'?'Both platforms':r.platform==='google'?'Google':'Meta'}</span></div><button class="metric-basis" data-action="metric-link" data-value="${r.metric}">${icon('link',11)}${esc(r.basis)}</button><p>${esc(f.editedAction||r.action)}</p><p style="font-size:10px;margin-top:6px;color:#98a38c">Expected impact: ${esc(r.impact)}</p><div class="feedback-controls"><button class="vote ${f.rating===1?'selected':''}" ${!canEdit()?'disabled':''} data-action="vote" data-id="${c.id}" data-index="${i}" data-value="1" aria-label="Recommendation ${i+1}: useful" aria-pressed="${f.rating===1}">${icon('thumbUp',13)}</button><button class="vote ${f.rating===-1?'selected':''}" ${!canEdit()?'disabled':''} data-action="vote" data-id="${c.id}" data-index="${i}" data-value="-1" aria-label="Recommendation ${i+1}: not useful" aria-pressed="${f.rating===-1}">${icon('thumbDown',13)}</button><button class="btn ghost small" ${!canEdit()?'disabled':''} data-action="feedback" data-id="${c.id}" data-index="${i}">${icon('message',12)}${f.comment?'Edit feedback':'Add feedback'}</button><select data-rec-status="${i}" data-client="${c.id}" aria-label="Recommendation ${i+1} action status" ${!canEdit()?'disabled':''}>${[['todo','To do'],['doing','In progress'],['done','Done'],['wont_do','Won’t do']].map(([v,l])=>`<option value="${v}" ${(f.action_status||'todo')===v?'selected':''}>${l}</option>`).join('')}</select></div>${f.comment?`<div class="subtext" style="font-size:10px;margin-top:10px">Your note: ${esc(f.comment)}</div>`:''}${f.task_url?`<a class="text-link" style="font-size:10px;margin-top:7px" href="${esc(f.task_url)}" target="_blank" rel="noopener noreferrer">Open linked task ${icon('upRight',10)}</a>`:''}</article>`}).join('')}<div class="note-box" style="margin-top:18px">${icon('info',14)}${window.__LIVE?'Rules-based note from account totals. Campaign and ad breakdowns are not included. Confirm lead quality before acting.':'Sample review. Confirmed outcome counts inform lead quality; revenue is unavailable. Staff assess recommendations and action them outside this workspace.'}</div></div><div class="review-footer"><div class="review-meta">Review configuration v${c.settingsVersion||1} · generated 07:32 IST · ${c.confidence==null?'Rules-based':c.confidence+'% confidence'} · revision ${revision}${c.history?.length?`<br>${c.history.length} previous revision${c.history.length>1?'s':''} preserved with feedback. <button class="text-link" style="font-size:9px" data-action="review-history" data-id="${c.id}">View history</button>`:''}</div><div class="review-actions"><div><button class="btn small" ${!canEdit()?'disabled':''} data-action="${state.editReview?'save-review':'edit-review'}" data-id="${c.id}">${icon(state.editReview?'check':'edit',13)}${state.editReview?'Save edit':'Edit review'}</button><button class="btn small" ${!isAdmin()?'disabled':''} data-action="regenerate" data-id="${c.id}">${icon('refresh',12)}Regenerate</button></div><div><button class="btn small danger" ${!canEdit()||c.status==='rejected'?'disabled':''} data-action="review-status" data-id="${c.id}" data-value="rejected">Reject</button><button class="btn primary small" ${!canEdit()||c.status==='approved'?'disabled':''} data-action="review-status" data-id="${c.id}" data-value="approved">${icon('check',13)}${c.status==='approved'?'Approved':'Approve review'}</button></div></div></div></section>`}
function reviewQueue(){const all=clients().filter(c=>c.ai),needs=readyReviews();let list=(state.reviewFilter==='needs'?needs:state.reviewFilter==='all'?all:all.filter(c=>c.status===state.reviewFilter)).filter(c=>c.name.toLowerCase().includes(state.search.toLowerCase()));const order={high:0,medium:1,low:2,none:3};list.sort((a,b)=>(order[a.severity]-order[b.severity])||(aggregate(clientAccounts(b.id),[window.__LIVE?window.__LIVE.endDate:22]).spend-aggregate(clientAccounts(a.id),[window.__LIVE?window.__LIVE.endDate:22]).spend));return heading('A second opinion. Your final call.','Turn performance signals into thoughtful next steps.',`<button class="btn" data-action="export-reviews">${icon('download',14)}Export reviews</button>`,'REVIEW WORKSPACE')+`<div class="queue-summary"><div class="stat-pill"><strong>${needs.length}</strong><span>Need a look</span></div><div class="stat-pill"><strong>${needs.filter(c=>c.severity==='high').length}</strong><span>High priority</span></div><div class="stat-pill"><strong>${all.filter(c=>c.status==='approved').length}</strong><span>Approved</span></div><div class="stat-pill"><strong>${all.filter(c=>c.status==='skipped').length}</strong><span>Skipped · zero spend</span></div></div><div class="notice">${icon('spark',17)}<span><strong>You’re in control.</strong> Reviews are staff-facing. Approving a review does not send it to a client or change any ad.</span></div><div class="filterbar"><div class="segmented">${[['needs','Needs a look'],['all','All reviews'],['approved','Approved'],['skipped','Skipped']].map(([v,l])=>`<button class="${state.reviewFilter===v?'active':''}" data-action="review-filter" data-value="${v}">${l}</button>`).join('')}</div><span class="date-label">${icon('calendar',12)} ${window.__LIVE?dateFormat(window.__LIVE.endDate):'22 Oct 2026'}</span></div>${state.selectedReviews.size?`<div class="bulkbar"><span>${state.selectedReviews.size} selected</span><button class="btn small" data-action="mark-seen" ${!canEdit()?'disabled':''}>${icon('eye',12)}Mark seen</button><button class="btn ghost small" data-action="clear-selection">Clear</button></div>`:''}<section class="card table-card"><div class="card-header"><div class="table-title"><h2>Review queue</h2><span class="subcount">${list.length}</span></div><label class="search-field">${icon('search',12)}<input data-search="reviews" value="${esc(state.search)}" placeholder="Search clients..." aria-label="Search reviews"/></label></div><div class="table-scroll"><table class="review-table"><thead><tr><th class="checkbox-cell"><input type="checkbox" data-select-all aria-label="Select visible reviews" ${list.length&&list.every(c=>state.selectedReviews.has(c.id))?'checked':''} ${!canEdit()?'disabled':''}/></th><th>Client</th><th>Severity</th><th>Summary</th><th>Recommendations</th><th>Confidence</th><th>Status</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td class="checkbox-cell"><input type="checkbox" data-select-review="${c.id}" aria-label="Select ${esc(c.name)}" ${state.selectedReviews.has(c.id)?'checked':''} ${!canEdit()?'disabled':''}/></td><td><a class="client-name-cell" href="#/clients/${c.id}/review">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>07:32 IST · rev ${c.revision||1}</small></div></a></td><td>${severity(c)}</td><td class="summary-cell">${esc(reviewSummary(c))}</td><td>${c.status==='skipped'?'—':recommendations(c).length}</td><td><div class="confidence">${c.confidence?`<span>${c.confidence}%</span><div class="progress-track"><div class="progress-fill" style="width:${c.confidence}%"></div></div>`:'—'}</div></td><td>${statusBadge(db.seen.includes(c.id)&&c.status==='ready'?'seen':c.status)}</td><td><a href="#/clients/${c.id}/review" class="btn small">Open ${icon('arrow',11)}</a></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty-state">'+icon('checkCircle',30)+'<h3>All caught up.</h3><p>No reviews match this view.</p></div></td></tr>'}</tbody></table></div></section>`+bottomNote()}
function flagList(list){return`<section class="card">${list.length?list.map(f=>{const c=clientById(f.client);return`<article class="flag-row"><div class="flag-icon ${f.severity}">${icon('flag',16)}</div><div class="flag-body"><h3>${esc(f.title)}<span class="badge ${f.severity==='critical'?'error':'warning'}">${f.severity==='critical'?'Critical':'Warning'}</span></h3><p>${esc(f.description)}</p><small>${esc(c.name)} · ${f.date} 2026 · ${f.audience}-visible flag</small></div><a href="#/clients/${c.id}" class="text-link flag-end">View client ${icon('arrow',12)}</a></article>`}).join(''):`<div class="empty-state">${icon('checkCircle',28)}<h3>Looking clear.</h3><p>No flags match this view.</p></div>`}</section>`}
function flagsPage(){let list=flags().filter(f=>state.flagFilter==='all'||f.severity===state.flagFilter);return heading('The signals worth your attention.','Spot changes early, then explore the context behind them.',`<button class="btn" data-action="go" data-value="settings/system">${icon('settings',13)}Flag thresholds</button>`,'FLAGS & ALERTS')+`<div class="queue-summary"><div class="stat-pill"><strong>${flags().length}</strong><span>Open flags</span></div><div class="stat-pill"><strong>${flags().filter(f=>f.severity==='critical').length}</strong><span>Critical</span></div><div class="stat-pill"><strong>${flags().filter(f=>f.severity==='warn').length}</strong><span>Warnings</span></div><div class="stat-pill"><strong>${flags().filter(f=>f.type==='data_stale').length}</strong><span>Data freshness issues</span></div></div><div class="filterbar"><div class="segmented">${[['all','All flags'],['critical','Critical'],['warn','Warnings']].map(([v,l])=>`<button class="${state.flagFilter===v?'active':''}" data-action="flag-filter" data-value="${v}">${l}</button>`).join('')}</div><span class="date-label">Report date · ${window.__LIVE?dateFormat(window.__LIVE.endDate):'22 Oct 2026'}</span></div>`+flagList(list)+bottomNote()}
function accountTable(list=accounts(),mapping=false){return`<section class="card table-card"><div class="card-header"><div class="table-title"><h2>${mapping?'Account mapping':'Connected accounts'}</h2><span class="subcount">${list.length}</span></div><span class="date-label">Connected reporting source</span></div><div class="table-scroll"><table><thead><tr><th>Account</th><th>Platform</th><th>${mapping?'Mapped client':'Status'}</th><th>Currency</th><th>Spend</th><th>Leads</th><th>Last synced</th><th></th></tr></thead><tbody>${list.map(a=>{const original=baseClients.find(c=>c.id===baseAccounts.find(b=>b.id===a.id).client),m=aggregate([a],days());return`<tr><td><div class="client-name-cell">${platformIcon(a.platform)}<div><strong>${esc(a.name||original?.name||'Account')} · ${a.platform==='meta'?'Meta':'Google'}</strong><small>${esc(a.externalId||a.id)}</small></div></div></td><td>${a.platform==='meta'?'Meta Ads':'Google Ads'}</td><td>${mapping?`<select class="account-map" data-account-map="${a.id}" aria-label="Map ${original.name} ${a.platform} account" ${!isAdmin()?'disabled':''}><option value="">Unmapped</option>${clients().filter(c=>c.currency===a.currency).map(c=>`<option value="${c.id}" ${c.id===a.client?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:`<span class="badge ${a.client?'success':'warning'}">${a.client?'Mapped':'Unmapped'}</span>`}</td><td>${a.currency}</td><td>${money(m.spend,a.currency)}</td><td>${num(m.leads)}</td><td style="color:#9ca88d;font-size:10px">${window.__LIVE?esc(window.__LIVE.syncedLabel.replace('Live Meta sync · ','')):'08:20 IST'}</td><td><a href="#/accounts/${a.id}" class="icon-btn" aria-label="Open ${original.name} ${a.platform} account">${icon('chevron',12)}</a></td></tr>`}).join('')||'<tr><td colspan="8"><div class="empty-state">No accounts in this view.</div></td></tr>'}</tbody></table></div></section>`}
function accountsPage(){if(state.accountId){const a=accounts().find(x=>x.id===state.accountId),c=baseClients.find(c=>c.id===baseAccounts.find(x=>x.id===a.id).client);return heading(`${esc(c.name)} · ${a.platform==='meta'?'Meta Ads':'Google Ads'}`,'Daily performance, with a clear view of data freshness.',`<button class="btn" data-action="export-account" data-id="${a.id}">${icon('download',14)}Export daily data</button>`,'AD ACCOUNT')+`<div class="notice">${icon('info',16)}${a.name?esc(a.name)+' · ':''}${a.currency} · mapped to ${a.client?esc(clientById(a.client).name):'no client'} · ${window.__LIVE?esc(window.__LIVE.syncedLabel):'last sample sync 08:20 IST'}</div><section class="card"><div class="card-header"><h2>Daily performance</h2><span class="badge neutral">Account status unavailable</span></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Spend</th><th>Impressions</th><th>Clicks</th><th>CTR</th><th>Leads</th><th>Cost / lead</th></tr></thead><tbody>${(window.__LIVE?Array.from({length:7},(_,i)=>shiftISO(window.__LIVE.endDate,-i)):[22,21,20,19,18,17,16]).map(d=>{const m=aggregate([a],[d]);return`<tr><td>${dateFormat(d)}</td><td>${money(m.spend,a.currency)}</td><td>${num(m.impressions)}</td><td>${num(m.clicks)}</td><td>${pct(m.ctr)}</td><td>${num(m.leads)}</td><td>${money(m.cpa,a.currency)}</td></tr>`}).join('')}</tbody></table></div></section>`+bottomNote()}const list=accounts().filter(a=>state.accountFilter==='all'||(state.accountFilter==='unmapped'?!a.client:a.platform===state.accountFilter));return heading('Every account, accounted for.','Review connections and keep client mappings in order.',`<button class="btn" data-action="go" data-value="settings/accounts">${icon('link',14)}Manage mapping</button>`,'AD ACCOUNTS')+`<div class="queue-summary"><div class="stat-pill"><strong>${accounts().length}</strong><span>Ad accounts</span></div><div class="stat-pill"><strong>${accounts().filter(a=>a.platform==='meta').length}</strong><span>Meta accounts</span></div><div class="stat-pill"><strong>${accounts().filter(a=>a.platform==='google').length}</strong><span>Google accounts</span></div><div class="stat-pill"><strong>${accounts().filter(a=>!a.client).length}</strong><span>Unmapped</span></div></div><div class="filterbar"><div class="segmented">${[['all','All accounts'],['meta','Meta Ads'],['google','Google Ads'],['unmapped','Unmapped']].map(([v,l])=>`<button class="${state.accountFilter===v?'active':''}" data-action="account-filter" data-value="${v}">${l}</button>`).join('')}</div><span class="freshness"><span class="dot"></span>${window.__LIVE?esc(window.__LIVE.syncedLabel):'Sample sync · 08:20 IST'}</span></div>`+accountTable(list)+bottomNote()}
function reportText(c){return v3.reportText(c.id)}
function reportsPage(){return v3.reportsPage()}
function clientConfig(c){return v3.clientConfig(c)}
function settingsPage(){const tabs=[['clients','Clients'],['accounts','Accounts'],['statuses','Lead statuses'],['staff','Staff & roles'],['system','System'],['ai','AI settings']];const content=state.settingsTab==='clients'?v3.settingsClients():state.settingsTab==='accounts'?accountTable(accounts(),true):state.settingsTab==='statuses'?v3.statusSettings():state.settingsTab==='staff'?staffSettings():state.settingsTab==='system'?systemSettings():isAdmin()?aiSettings():'<section class="card"><div class="empty-state">Admin access required.</div></section>';return heading('Make the workspace work for you.','Manage reporting, lead outcomes, access, and review preferences.','','WORKSPACE SETTINGS')+`<div class="tabs">${tabs.map(([v,l])=>`<a class="${state.settingsTab===v?'active':''}" href="#/settings/${v}">${l}</a>`).join('')}</div>`+content+bottomNote()}

function staffSettings(){return`<div class="notice">${icon('shield',16)}Preview role controls affect this UI only. Production authentication and staff permissions require the backend in your brief.</div><section class="card table-card"><div class="card-header"><h2>Staff allowlist</h2><button class="btn small" ${!isAdmin()?'disabled':''} data-action="add-staff">${icon('plus',12)}Add staff</button></div><div class="table-scroll"><table><thead><tr><th>Staff member</th><th>Role</th><th>Access</th><th>Permissions</th></tr></thead><tbody>${db.staff.map((s,i)=>`<tr><td><div class="client-name-cell"><span class="avatar">${esc(s.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.email)} · sample</small></div></div></td><td><select class="account-map" data-staff-role="${i}" ${!isAdmin()||i===0?'disabled':''} aria-label="${esc(s.name)} role">${['admin','performance','staff'].map(r=>`<option value="${r}" ${s.role===r?'selected':''}>${r.charAt(0).toUpperCase()+r.slice(1)}</option>`).join('')}</select></td><td><button class="switch ${s.active?'on':''}" data-action="staff-active" data-index="${i}" role="switch" aria-checked="${s.active}" aria-label="${esc(s.name)} access" ${!isAdmin()||i===0?'disabled':''}></button></td><td style="font-size:10px;color:#92a080">${s.role==='admin'?'All workspace settings':s.role==='performance'?'Read, rate, edit, approve':'Read-only access'}</td></tr>`).join('')}</tbody></table></div></section>`}
function systemSettings(){return v3.systemSettings()}
function aiSettings(){return v3.aiSettings()}
function loginPage(){return`<div class="login-layout"><section class="login-art">${brand()}<div><h1>Less noise.<br>More perspective.</h1><p>Your clients, their performance, and the next right move. All in one considered workspace.</p><div class="art-lines">${[.28,.43,.36,.64,.56,.84,1].map(v=>`<i style="height:${v*100}%"></i>`).join('')}</div></div><small>CreativHeads® · Ad Reports · Staff workspace</small></section><section class="login-form"><div class="login-inner"><span class="badge success" style="margin-bottom:20px">AD REPORTS</span><h1>Welcome to your workspace.</h1><p>A clearer view of what’s working.</p><button class="btn" data-action="auth-preview"><span style="display:grid;grid-template-columns:repeat(2,7px);gap:2px">${['#f35325','#81bc06','#05a6f0','#ffba08'].map(c=>`<i style="height:7px;width:7px;background:${c}"></i>`).join('')}</span>Continue with Microsoft</button><div style="text-align:center;color:#a5b095;font-size:10px;margin:8px 0">UI PROTOTYPE</div><button class="btn primary" data-action="go" data-value="portfolio">Explore the demo workspace ${icon('arrow',15)}</button><div class="note-box">${icon('lock',14)}Microsoft authentication is a designed state. The interactive demo uses sample data and does not sign in to your organization.</div></div></section></div>`}
function render(){document.title=`${state.clientId?clientById(state.clientId).name:({portfolio:'Portfolio',clients:'Clients',accounts:'Ad accounts',reviews:'AI reviews',flags:'Flags & alerts',reports:'Client reports',feedback:'Lead feedback',settings:'Settings',login:'Welcome'}[state.page])} · CreativHeads Ad Reports`;if(state.page==='login'){document.getElementById('app').innerHTML=loginPage();return}let html=state.page==='portfolio'?portfolio():state.page==='clients'?state.clientId?clientPage():portfolio(true):state.page==='reviews'?reviewQueue():state.page==='flags'?flagsPage():state.page==='accounts'?accountsPage():state.page==='reports'?reportsPage():state.page==='feedback'?v3.feedbackPage():settingsPage();document.getElementById('app').innerHTML=sidebar()+`<div class="main-shell">${topbar()}<main id="main" class="content">${html}</main></div>`;bindChart()}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('toast-visible'),3300)}
let lastFocus=null;
function modal(title,body,footer='',wide=false){state.interactionVersion++;document.getElementById('toast')?.classList.remove('toast-visible');lastFocus=document.activeElement;document.getElementById('overlay-root').innerHTML=`<div class="overlay" data-action="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close',18)}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input,.modal textarea,.modal select,.modal button')?.focus(),10)}
function closeModal(restoreFocus=true){state.interactionVersion++;document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';if(restoreFocus&&lastFocus?.isConnected)lastFocus.focus?.();lastFocus=null}
function bindChart(){document.querySelectorAll('[data-chart-point]').forEach(el=>{const show=()=>{const t=el.closest('.chart-wrap').querySelector('.chart-tooltip');t.textContent=el.dataset.chartPoint;t.style.display='block';t.style.left=Math.max(20,Math.min(80,+el.dataset.pointX))+'%';t.style.top=Math.max(20,+el.dataset.pointY)+'%'};const hide=()=>el.closest('.chart-wrap').querySelector('.chart-tooltip').style.display='none';el.addEventListener('mouseenter',show);el.addEventListener('focus',show);el.addEventListener('mouseleave',hide);el.addEventListener('blur',hide)})}
const feedbackKey=(id,i)=>`${id}:${clientById(id).revision||1}:${i}`;
function exportCSV(filename,headers,rows){const cell=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"'};const text='\uFEFF'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample CSV exported.')}
function exportClients(){const list=state.clientId?[clientById(state.clientId)]:tableClients();exportCSV('CreativHeads_Sample_Ad_Report.csv',['Client','Currency','Period','Platform','Spend','Leads','Cost per lead','Clicks','Impressions','CTR %','Data'],list.map(c=>{const m=totals(c.id);return[c.name,c.currency,periodLabel(),state.platform,m.spend,m.leads,m.cpa?.toFixed(2)||'',m.clicks,m.impressions,m.ctr?.toFixed(2)||'','Illustrative sample']}))}
function searchResults(query=''){const q=query.toLowerCase();const pages=[['Portfolio','portfolio','Performance overview'],['AI reviews','reviews','Review, rate and approve'],['Flags & alerts','flags','Monitor performance changes'],['Client reports','reports','WhatsApp handoff and PDFs'],['Lead feedback','feedback/new','Paste, preview and confirm outcomes'],['Ad accounts','accounts','Accounts and mapping'],['Settings','settings/clients','Workspace configuration']];return [...clients().map(c=>[c.name,'clients/'+c.id,c.sector]),...pages].filter(r=>r.join(' ').toLowerCase().includes(q)).map(([name,path,desc])=>`<button data-action="go" data-value="${path}">${icon(path.startsWith('clients')?'users':'grid',16)}<span class="result-info"><strong>${esc(name)}</strong><small>${esc(desc)}</small></span>${icon('arrow',13)}</button>`).join('')||'<div class="empty-state">No results. Try a client or page name.</div>'}
function showSearch(){modal('Find your way',`<div class="search-modal"><label class="search-field">${icon('search',17)}<input id="global-search-input" aria-label="Search workspace" placeholder="Find a client, review or page..." autocomplete="off"/></label><div class="search-results">${searchResults()}</div></div>`)}
function profileModal(){modal('Preview the workspace as…',`<p>Try the permissions designed for each staff role. This changes the prototype view and does not grant production access.</p><div class="role-options">${[['admin','Admin'],['performance','Performance'],['staff','Read only']].map(([v,l])=>`<button class="${db.role===v?'active':''}" data-action="set-role" data-value="${v}">${l}</button>`).join('')}</div><div class="note-box">Admin: configuration and reviews. Performance: reviews and feedback. Staff: read-only views.</div>`,`<button class="btn" data-action="go" data-value="login">${icon('logout',13)}View sign-in screen</button><button class="btn primary" data-action="close">Done</button>`)}
function feedbackModal(id,index){const c=clientById(id),f=db.feedback[feedbackKey(id,index)]||{};modal('Recommendation feedback',`<form id="feedback-form" data-form="feedback" data-id="${id}" data-index="${index}"><div class="form-grid"><div class="field full"><label for="feedback-comment">Your context or feedback</label><textarea name="comment" id="feedback-comment" maxlength="1000" placeholder="What is useful? What should the reviewer know?">${esc(f.comment||'')}</textarea></div><div class="field"><label for="severity-override">Review severity</label><select id="severity-override" name="severity_override">${['low','medium','high'].map(v=>`<option value="${v}" ${(f.severity_override||c.severity)===v?'selected':''}>${v.charAt(0).toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="field"><label for="feedback-status">Action status</label><select id="feedback-status" name="action_status">${[['todo','To do'],['doing','In progress'],['done','Done'],['wont_do','Won’t do']].map(([v,l])=>`<option value="${v}" ${(f.action_status||'todo')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="task-url">Task link · optional</label><input id="task-url" name="task_url" type="url" placeholder="https://…" value="${esc(f.task_url||'')}"/></div><div class="field full"><label for="edited-action">Edit suggested action · optional</label><textarea id="edited-action" name="editedAction">${esc(f.editedAction||recommendations(c)[index].action)}</textarea><small>The original recommendation remains in the sample review.</small></div></div></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="feedback-form">Save feedback</button>`)}
document.addEventListener('click',async e=>{document.querySelectorAll('[data-picker][open]').forEach(d=>{if(!d.contains(e.target))d.removeAttribute('open')});const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,value,id,index}=el.dataset;if(action==='go'&&e.target.closest('a,button,input,select,textarea')!==el&&e.target.closest('a,button,input,select,textarea'))return;if(action==='overlay'&&e.target!==el)return;state.interactionVersion++;if(action?.startsWith('v3-')){e.preventDefault();e.stopPropagation();await v3.handleAction(el,e);return;}if(action==='overlay'){if(e.target!==el)return;closeModal();return}switch(action){
case'set-filter':state[el.dataset.key]=value;if(el.dataset.key==='clientFilter'&&value!=='all')state.currency=clientById(value).currency;state.search='';updateURL();render();document.querySelector(`[data-picker] [data-key="${el.dataset.key}"]`)?.closest('details')?.querySelector('summary')?.focus();break;case'go':go(value);break;case'menu':state.sidebar=!state.sidebar;document.querySelector('.sidebar')?.classList.toggle('open',state.sidebar);break;case'close':closeModal();break;case'search':showSearch();break;case'profile':profileModal();break;
case'set-role':db.role=value;persist();render();closeModal();toast(`Previewing ${value==='staff'?'read-only staff':value} access.`);break;
case'help':case'workspace':modal('Ad Reports, by CreativHeads',`<p>A focused performance workspace based on your developer brief: portfolio visibility, campaign drill-down, confirmed lead outcomes, AI review feedback, WhatsApp handoffs and client PDFs.</p><p><strong>This is an interactive UI prototype.</strong> All metrics, accounts, review text and delivery logs are sample content. Feedback and settings are saved in this browser.</p><p>Use the profile menu to explore staff permissions. Live data, authentication, AI generation and delivery to the internal staff group require the backend. Client WhatsApp sharing is manual.</p>`,`<button class="btn" data-action="reset-preview">Reset sample data</button><button class="btn" data-action="go" data-value="login">View sign-in design</button><button class="btn primary" data-action="close">Explore workspace</button>`);break;
case'notifications':modal('Workspace activity',`<div class="note-box" style="margin-bottom:15px">Illustrative activity for 23 October 2026</div><div class="versions"><div class="version-row">${icon('spark',17)}<div class="version-info">${readyReviews().length} reviews need a look<small>Review queue · 07:32 IST</small></div><button class="text-link" data-action="go" data-value="reviews">Open</button></div><div class="version-row">${icon('flag',17)}<div class="version-info">${flags().length} performance flags<small>Latest report date · 22 Oct</small></div><button class="text-link" data-action="go" data-value="flags">View</button></div><div class="version-row">${icon('send',17)}<div class="version-info">Daily report previews are ready<small>Internal delivery · Performance | CH</small></div><button class="text-link" data-action="go" data-value="reports">View</button></div></div>`);break;
case'currency':state.currency=value;state.clientFilter='all';state.search='';updateURL();render();break;case'chart-metric':state.metric=value;render();break;case'chart-range':state.chartRange=state.chartRange===7?14:7;render();break;
case'export':exportClients();break;case'export-account':{const a=accounts().find(a=>a.id===id);exportCSV('CreativHeads_Sample_Account.csv',['Date','Currency','Spend','Impressions','Clicks','Leads','CPA','CTR'],(window.__LIVE?Array.from({length:7},(_,i)=>shiftISO(window.__LIVE.endDate,-i)):[22,21,20,19,18,17,16]).map(d=>{const m=aggregate([a],[d]);return[dateFormat(d),a.currency,m.spend,m.impressions,m.clicks,m.leads,m.cpa?.toFixed(2)||'',m.ctr?.toFixed(2)||'']}));break}
case'export-reviews':exportCSV('CreativHeads_Sample_Reviews.csv',['Client','Report date','Revision','Status','Severity','Recommendation','Priority','Action','Rating','Comment','Task URL'],clients().filter(c=>c.status!=='skipped').flatMap(c=>recommendations(c).map((r,i)=>{const f=db.feedback[feedbackKey(c.id,i)]||{};return[c.name,'2026-10-22',c.revision||1,c.status,c.severity,r.title,r.priority,f.editedAction||r.action,f.rating||'',f.comment||'',f.task_url||'']})));break;
case'sort':state.sortDirection=state.sort===value?-state.sortDirection:value==='name'?1:-1;state.sort=value;render();break;
case'table-filters':modal('Filter client performance',`<form id="filter-form" data-form="filters"><div class="form-grid"><div class="field"><label>Currency</label><select name="tableCurrency"><option value="all" ${state.tableCurrency==='all'?'selected':''}>All currencies</option><option value="INR" ${state.tableCurrency==='INR'?'selected':''}>INR · Indian rupee</option><option value="AED" ${state.tableCurrency==='AED'?'selected':''}>AED · UAE dirham</option></select></div><div class="field"><label>Platform</label><select name="platform"><option value="all">All platforms</option><option value="meta" ${state.platform==='meta'?'selected':''}>Meta Ads</option><option value="google" ${state.platform==='google'?'selected':''}>Google Ads</option></select></div></div><p style="margin-top:17px">Client rows retain their own currency. Portfolio totals use the separate totals-currency control.</p></form>`,`<button class="btn" data-action="reset-filters">Reset filters</button><button class="btn primary" form="filter-form" type="submit">Apply filters</button>`);break;
case'reset-filters':state.currency='INR';state.tableCurrency='all';state.platform='all';state.clientFilter='all';state.search='';updateURL();closeModal();render();break;
case'client-tab':go('clients/'+state.clientId+'/'+value);break;case'review-filter':state.reviewFilter=value;state.selectedReviews.clear();render();break;case'flag-filter':state.flagFilter=value;render();break;case'account-filter':state.accountFilter=value;render();break;
case'vote':{if(!canEdit())return;const k=feedbackKey(id,index),old=db.feedback[k]||{};db.feedback[k]={...old,rating:old.rating===+value?0:+value};persist();render();toast('Recommendation feedback saved locally.');break}
case'feedback':if(canEdit())feedbackModal(id,+index);break;
case'review-status':{if(!canEdit())return;db.reviews[id]={...db.reviews[id],status:value,reviewedAt:new Date().toISOString()};persist();render();toast(value==='approved'?'Review approved in this browser. Nothing was sent.':'Review rejected. Feedback remains available.');break}
case'edit-review':if(!canEdit())return;state.editReview=true;render();document.getElementById('review-edit')?.focus();break;
case'save-review':if(!canEdit())return;{const text=document.getElementById('review-edit').value.trim();if(!text){toast('Add a summary before saving.');return}db.reviews[id]={...db.reviews[id],editedSummary:text};state.editReview=false;persist();render();toast('Edited summary saved. Original review preserved.');break}
case'regenerate':if(!isAdmin())return;modal('Preview a new review revision',`<p>Regenerating preserves the existing review and its feedback as revision ${clientById(id).revision||1}, then opens a fresh revision for review.</p><div class="note-box" style="margin-top:17px">${icon('info',16)}This is a simulation. No model is called and no cost is incurred. The production flow would show an estimate before generation.</div>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="confirm-regenerate" data-id="${id}">${icon('refresh',13)}Simulate regeneration</button>`);break;
case'confirm-regenerate':{if(!isAdmin())return;const c=clientById(id);db.reviews[id]={status:'ready',severity:baseClients.find(x=>x.id===id).severity,revision:(c.revision||1)+1,confidence:c.confidence,model:db.settings.model,promptVersion:db.settings.promptVersion,settingsVersion:db.settingsVersion,history:[...(c.history||[]),{revision:c.revision||1,summary:reviewSummary(c),status:c.status,severity:c.severity}]};db.seen=db.seen.filter(x=>x!==id);persist();closeModal();render();toast(`Revision ${db.reviews[id].revision} created.`);fetch('/api/review',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id,name:c.name,currency:c.currency,metrics:aggregate(clientAccounts(id),[window.__LIVE?window.__LIVE.endDate:22])})}).then(r=>r.json()).then(j=>{if(!j.summary)return;db.reviews[id]={...db.reviews[id],editedSummary:j.summary,severity:j.severity||db.reviews[id].severity};persist();render()}).catch(()=>{});break}
case'review-history':{const c=clientById(id);modal('Previous review revisions',(c.history||[]).slice().reverse().map(h=>`<div style="padding:15px 0;border-bottom:1px solid #e5ebdd"><div class="section-head"><h3>Revision ${h.revision}</h3>${statusBadge(h.status)}</div><p>${esc(h.summary)}</p><small style="color:#95a587">${Object.keys(db.feedback).filter(k=>k.startsWith(id+':'+h.revision+':')).length} feedback records preserved</small></div>`).join(''));break}
case'metric-link':{if(value==='cost_per_booking'){go('clients/'+state.clientId+'/quality');break}go('clients/'+state.clientId+'/overview');setTimeout(()=>{const tile=document.getElementById('metric-'+value);tile?.scrollIntoView({behavior:'smooth',block:'center'});tile?.classList.add('highlight')},100);break}
case'mark-seen':if(!canEdit())return;db.seen=[...new Set([...db.seen,...state.selectedReviews])];state.selectedReviews.clear();persist();render();toast('Selected reviews marked seen.');break;case'clear-selection':state.selectedReviews.clear();render();break;
case'select-report':state.selectedReport=id;render();break;case'report-client':state.selectedReport=id;go('reports');break;
case'client-toggle':{if(!isAdmin())return;const c=clientById(id);db.clients[id]={...db.clients[id],[value]:!c[value]};persist();if(document.querySelector('[data-form="client"]')){el.classList.toggle('on',!c[value]);el.setAttribute('aria-checked',String(!c[value]))}else render();toast('Preview preference saved locally.');break}
case'staff-active':if(!isAdmin()||+index===0)return;db.staff[+index].active=!db.staff[+index].active;persist();render();break;
case'add-staff':if(!isAdmin())return;modal('Add staff to the preview',`<form id="staff-form" data-form="staff"><div class="form-grid"><div class="field full"><label for="staff-name">Display name</label><input id="staff-name" name="name" required maxlength="60"/></div><div class="field full"><label for="staff-email">Email</label><input id="staff-email" name="email" type="email" required/></div><div class="field full"><label for="staff-role">Role</label><select id="staff-role" name="role"><option value="staff">Staff · read only</option><option value="performance">Performance · review & approve</option><option value="admin">Admin · full workspace</option></select></div></div><p style="margin-top:15px">Saved only to this browser. No invitation or email is sent.</p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" form="staff-form" type="submit">Add to preview</button>`);break;
case'test-review':if(!isAdmin())return;modal('Test preview',`<div class="form-grid"><div class="field"><label>Client</label><select id="test-client">${clients().filter(c=>c.status!=='skipped').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Report date</label><input type="date" value="2026-10-22" min="2026-10-22" max="2026-10-22"/></div></div><div class="note-box" style="margin-top:18px">A sample result will be displayed. No AI request is made and no review is saved.</div>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="show-test-result">Show sample result</button>`);break;
case'show-test-result':{const c=clientById(document.getElementById('test-client').value);modal('Sample test result',`<div class="section-head"><h3>${esc(c.name)} · 22 Oct</h3>${severity(c)}</div><p>${esc(reviewSummary(c))}</p><div class="note-box" style="margin-top:18px">Sample output only. No changes were saved and the configured prompt was not executed.</div>`,'<button class="btn primary" data-action="close">Done</button>');break}
case'version-diff':{const v=db.versions.find(v=>v.version===+index);if(!v)return;const changes=Object.keys(db.settings).filter(k=>v.settings[k]!==db.settings[k]);modal(`Version ${v.version} → ${db.settingsVersion}`,`<p>${changes.length} configuration fields changed.</p><div class="versions" style="margin-top:12px">${changes.map(k=>`<div class="version-row" style="display:block"><strong>${esc(k)}</strong><p style="font-size:10px;overflow-wrap:anywhere"><span style="color:#b28b7c">Previous: ${esc(v.settings[k])}</span><br><span style="color:#688753">Active: ${esc(db.settings[k])}</span></p></div>`).join('')||'<p>There are no field differences.</p>'}</div>`);break}
case'reset-preview':modal('Restore sample workspace?', '<p>This resets the demo feedback, client preferences, and settings stored in this browser to the original sample values.</p>', '<button class="btn" data-action="close">Keep changes</button><button class="btn primary" data-action="confirm-reset">Restore sample data</button>');break;case'confirm-reset':Object.keys(db).forEach(k=>delete db[k]);Object.assign(db,structuredClone(defaults));persist();closeModal();location.href=location.pathname+'#/portfolio';location.reload();return;state.currency='INR';state.platform='all';state.clientFilter='all';state.period='yesterday';updateURL();go('portfolio');toast('Sample workspace restored.');break;case'auth-preview':modal('Microsoft sign-in',`<p>This is the sign-in screen design. Production authentication will use your Microsoft 365 tenant and the staff allowlist from the brief.</p><p>You can explore all screens now with the sample workspace.</p>`,`<button class="btn primary" data-action="go" data-value="portfolio">Enter demo workspace ${icon('arrow',13)}</button>`);break;
}});
document.addEventListener('toggle',e=>{if(e.target.matches?.('[data-picker]'))e.target.querySelector('summary')?.setAttribute('aria-expanded',String(e.target.open))},true);
document.addEventListener('input',e=>{if(v3.handleInput(e))return;if(e.target.id==='global-search-input'){document.querySelector('.search-results').innerHTML=searchResults(e.target.value);return}if(e.target.dataset.search){const input=e.target,val=input.value,pos=input.selectionStart;state.search=val;render();const next=document.querySelector('[data-search]');next?.focus();next?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(v3.handleChange(e))return;const el=e.target;if(el.dataset.filter){closeModal(false);state[el.dataset.filter]=el.value;if(el.dataset.filter==='clientFilter'&&el.value!=='all')state.currency=clientById(el.value).currency;state.search='';updateURL();render()}if(el.dataset.selectReview&&canEdit()){if(el.checked)state.selectedReviews.add(el.dataset.selectReview);else state.selectedReviews.delete(el.dataset.selectReview);render()}if(el.hasAttribute('data-select-all')&&canEdit()){document.querySelectorAll('[data-select-review]').forEach(x=>{if(el.checked)state.selectedReviews.add(x.dataset.selectReview);else state.selectedReviews.delete(x.dataset.selectReview)});render()}if(el.hasAttribute('data-rec-status')&&canEdit()){const k=feedbackKey(el.dataset.client,el.dataset.recStatus);db.feedback[k]={...db.feedback[k],action_status:el.value};persist();toast('Action status saved locally.')}if(el.dataset.accountMap&&isAdmin()){db.mapping[el.dataset.accountMap]=el.value;persist();render();toast(el.value?'Account mapping updated locally.':'Account moved to Unmapped.')}if(el.hasAttribute('data-staff-role')&&isAdmin()&&+el.dataset.staffRole!==0){db.staff[+el.dataset.staffRole].role=el.value;persist();render();toast('Staff role updated in this preview.')}});
document.addEventListener('submit',e=>{if(v3.handleSubmit(e))return;const form=e.target;if(!form.dataset.form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));switch(form.dataset.form){case'filters':Object.assign(state,data,{clientFilter:'all'});updateURL();closeModal();render();break;case'client':if(!isAdmin())return;db.clients[form.dataset.id]={...db.clients[form.dataset.id],...data,budget:Number(data.budget)};persist();render();toast('Client configuration saved locally.');break;case'feedback':if(!canEdit())return;if(data.task_url&&!/^https?:\/\//i.test(data.task_url)){toast('Use an http or https link for the task.');return}db.feedback[feedbackKey(form.dataset.id,form.dataset.index)]={...db.feedback[feedbackKey(form.dataset.id,form.dataset.index)],...data};db.reviews[form.dataset.id]={...db.reviews[form.dataset.id],severity:data.severity_override};persist();closeModal();render();toast('Feedback saved to this review revision.');break;case'thresholds':if(!isAdmin())return;db.thresholds=Object.fromEntries(Object.entries(data).map(([k,v])=>[k,Number(v)]));persist();toast('Threshold configuration saved locally.');break;case'staff':if(!isAdmin())return;if(db.staff.some(s=>s.email.toLowerCase()===data.email.toLowerCase())){toast('This email is already in the preview allowlist.');return}db.staff.push({...data,active:true});persist();closeModal();render();toast('Staff member added locally. No invitation sent.');break;case'ai':if(!isAdmin())return;try{JSON.parse(data.schema)}catch{toast('The output shape must contain valid JSON.');return}db.versions.push({version:db.settingsVersion,settings:structuredClone(db.settings),note:data.changeNote});db.settingsVersion++;delete data.changeNote;db.settings=data;persist();render();toast(`Settings saved as version ${db.settingsVersion}.`);break}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();showSearch()}if(e.target.matches('[role="option"]')&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const options=[...e.target.parentElement.querySelectorAll('[role="option"]')],i=options.indexOf(e.target);options[e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}if(e.key==='Escape'){document.querySelectorAll('[data-picker][open]').forEach(d=>{d.removeAttribute('open');d.querySelector('summary')?.focus()});closeModal();state.sidebar=false;document.querySelector('.sidebar')?.classList.remove('open')}if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click();const modalEl=document.querySelector('.modal');if(modalEl&&e.key==='Tab'){const els=[...modalEl.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
const v3=createV3({state,db,clients,clientById,accounts,clientAccounts,aggregate,metricRow,days,icon,esc,num,money,pct,delta,calcDelta,avatar,platformIcon,platformIcons,severity,statusBadge,canEdit,isAdmin,heading,filters,picker,metricCards,chart,budgetCard,platformSplit,accountTable,reviewPanel,flagList,bottomNote,render,go,modal,closeModal,toast,persist,updateURL,flags});
window.addEventListener('hashchange',route);route();
